var n=[{title:`Qué describen los patrones`,text:`Una sentadilla flexiona y extiende sobre todo las caderas, las rodillas y los tobillos a la vez. Una bisagra se mueve sobre todo en las caderas, mientras que las zancadas y las subidas al escalón cargan una pierna cada vez. El empuje aleja la resistencia del cuerpo y el tirón la acerca hacia él. En un acarreo mantienes una carga estable mientras caminas, los ejercicios de core resisten o producen movimiento del tronco y la locomoción abarca caminar, correr y movimientos similares.`},{title:`Por qué importan los patrones`,text:`Un ejercicio puede entrenar varios músculos y patrones a la vez. Una sentadilla goblet entrena las piernas y el tronco, y un acarreo con carga entrena el agarre, la postura y la mecánica de la marcha. Clasificar los ejercicios por patrón muestra huecos que una lista ordenada solo por pecho, brazos y piernas puede pasar por alto. No necesitas todos los patrones en cada entrenamiento.`},{title:`Construir una semana equilibrada`,text:`En dos o tres sesiones de cuerpo completo, un principiante podría incluir una sentadilla, una bisagra de cadera, un empuje horizontal, un tirón horizontal, una zancada y un ejercicio sencillo de antirrotación o antiextensión. El empuje vertical, el tirón vertical y los acarreos pueden entrar cuando tu equipamiento, tu movilidad y tus objetivos lo permitan. Mantén la dosis de cada patrón lo bastante pequeña para poder recuperarte, y omite los ejercicios que no necesites.`},{title:`Ajusta los patrones a tu capacidad`,text:`Cada patrón tiene variantes más fáciles y más difíciles. Una sentadilla con silla puede ir antes que una sentadilla goblet, y una flexión en la pared antes que una flexión en el suelo. Un remo en polea y un remo con mancuerna son ambos tirones horizontales, pero exigen equilibrio y equipamiento distintos. Si un movimiento causa molestias o se siente inestable, cambia la variante y mantén el patrón.`},{title:`Cómo usar TrainUp`,text:`Cada página de ejercicio en Ejercicios muestra su patrón de movimiento, para que puedas comprobar cómo los cubre tu semana planificada. Si la mayoría de las sesiones tienen empuje y casi nada de tirón, un remo o un jalón que encaje con tu equipamiento y tus limitaciones cubriría el hueco. Busca una buena cobertura a lo largo de las semanas, no una proporción perfecta en cada sesión.`}];var i=[{label:`NSCA: seguridad y fundamentos del entrenamiento de fuerza`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Biblioteca de ejercicios de ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var s={sections:n,sources:i};export{s as default,n as sections,i as sources};